{
  "items": [
    {
      "name": "Real.geom_mean_le_arith_mean_weighted",
      "module_name": "Mathlib.Analysis.MeanInequalities",
      "kind": "theorem",
      "type": "∀ {ι : Type u} (s : Finset ι) (w z : ι → ℝ),\n  (∀ i ∈ s, 0 ≤ w i) → ∑ i ∈ s, w i = 1 → (∀ i ∈ s, 0 ≤ z i) → ∏ i ∈ s, z i ^ w i ≤ ∑ i ∈ s, w i * z i"
    },
    {
      "name": "BoundingSieve.weights",
      "module_name": "Mathlib.NumberTheory.SelbergSieve",
      "kind": "definition",
      "type": "BoundingSieve → ℕ → ℝ"
    },
    {
      "name": "Multipliable.eventually_bounded_finset_prod",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Log.Summable",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {v : ι → ℝ}, Multipliable v → ∃ r₁ > 0, ∃ s₁, ∀ (t : Finset ι), s₁ ⊆ t → ∏ i ∈ t, v i ≤ r₁"
    },
    {
      "name": "controlled_prod_of_mem_closure",
      "module_name": "Mathlib.Analysis.Normed.Group.Continuity",
      "kind": "theorem",
      "type": "∀ {E : Type u_5} [inst : SeminormedCommGroup E] {a : E} {s : Subgroup E},\n  a ∈ closure ↑s →\n    ∀ {b : ℕ → ℝ},\n      (∀ (n : ℕ), 0 < b n) →\n        ∃ v,\n          Filter.Tendsto (fun n => ∏ i ∈ Finset.range (n + 1), v i) Filter.atTop (nhds a) ∧\n            (∀ (n : ℕ), v n ∈ s) ∧ ‖v 0 / a‖ < b 0 ∧ ∀ (n : ℕ), 0 < n → ‖v n‖ < b n"
    },
    {
      "name": "NNReal.geom_mean_le_arith_mean_weighted",
      "module_name": "Mathlib.Analysis.MeanInequalities",
      "kind": "theorem",
      "type": "∀ {ι : Type u} (s : Finset ι) (w z : ι → NNReal), ∑ i ∈ s, w i = 1 → ∏ i ∈ s, z i ^ ↑(w i) ≤ ∑ i ∈ s, w i * z i"
    },
    {
      "name": "Real.geom_mean_lt_arith_mean_weighted_iff_of_pos",
      "module_name": "Mathlib.Analysis.MeanInequalities",
      "kind": "theorem",
      "type": "∀ {ι : Type u} (s : Finset ι) (w z : ι → ℝ),\n  (∀ i ∈ s, 0 < w i) →\n    ∑ i ∈ s, w i = 1 → (∀ i ∈ s, 0 ≤ z i) → (∏ i ∈ s, z i ^ w i < ∑ i ∈ s, w i * z i ↔ ∃ j ∈ s, ∃ k ∈ s, z j ≠ z k)"
    },
    {
      "name": "Real.exists_int_int_abs_mul_sub_le",
      "module_name": "Mathlib.NumberTheory.DiophantineApproximation.Basic",
      "kind": "theorem",
      "type": "∀ (ξ : ℝ) {n : ℕ}, 0 < n → ∃ j k, 0 < k ∧ k ≤ ↑n ∧ |↑k * ξ - ↑j| ≤ 1 / (↑n + 1)"
    },
    {
      "name": "Real.geom_mean_le_arith_mean4_weighted",
      "module_name": "Mathlib.Analysis.MeanInequalities",
      "kind": "theorem",
      "type": "∀ {w₁ w₂ w₃ w₄ p₁ p₂ p₃ p₄ : ℝ},\n  0 ≤ w₁ →\n    0 ≤ w₂ →\n      0 ≤ w₃ →\n        0 ≤ w₄ →\n          0 ≤ p₁ →\n            0 ≤ p₂ →\n              0 ≤ p₃ →\n                0 ≤ p₄ →\n                  w₁ + w₂ + w₃ + w₄ = 1 → p₁ ^ w₁ * p₂ ^ w₂ * p₃ ^ w₃ * p₄ ^ w₄ ≤ w₁ * p₁ + w₂ * p₂ + w₃ * p₃ + w₄ * p₄"
    }
  ]
}
